// Compare the full formatter/chronology chain with independently exported .NET
// month anchors. Supply general_datetime_core/test/fixtures/chinese_dotnet_months.json
// from the chronology repository, regenerated by tool/export_chinese_oracle.ps1.
// English names below are the pinned CLDR 48 traditional month names, not
// values read back from the implementation being validated.
import 'dart:convert';
import 'dart:io';
import 'package:general_date_format_core/general_date_format_core.dart';
import 'package:general_datetime_core/general_datetime_core.dart';

void main(List<String> args) {
  if (args.length != 1) {
    stderr.writeln(
        'Usage: dart tool/validate_chinese_oracle.dart <dotnet-month-fixture.json>');
    exitCode = 64;
    return;
  }
  final rows = jsonDecode(File(args.single).readAsStringSync()) as List;
  if (rows.length != 2461) {
    throw StateError('Expected all 2,461 month fixtures.');
  }
  const names = [
    'First Month',
    'Second Month',
    'Third Month',
    'Fourth Month',
    'Fifth Month',
    'Sixth Month',
    'Seventh Month',
    'Eighth Month',
    'Ninth Month',
    'Tenth Month',
    'Eleventh Month',
    'Twelfth Month'
  ];
  final numeric = GeneralDateFormat('yyyy-MM-dd HH:mm:ss.SSSSSS', 'en');
  final named = GeneralDateFormat('dd MMMM yyyy HH:mm:ss.SSSSSS', 'en');
  final selector = ChineseDateTime.utc(2024);
  var days = 0, parses = 0;
  void equal(Object actual, Object expected, String context) {
    if (actual != expected) {
      throw StateError('$context expected=$expected actual=$actual');
    }
  }

  for (final row in rows) {
    final anchor = DateTime.parse('${row[0]}T12:34:56.123457Z');
    for (var day = 1; day <= row[5]; day++) {
      final expected = anchor.add(Duration(days: day - 1));
      final date =
          ChineseDateTime.utc(row[1], row[2], day, 12, 34, 56, 123, 457);
      final prefix =
          '${row[1]}-${row[2].toString().padLeft(2, '0')}-${day.toString().padLeft(2, '0')}';
      final number = '$prefix 12:34:56.123457';
      final month =
          '${names[(row[3] as int) - 1]}${row[4] == true ? 'bis' : ''}';
      final text =
          '${day.toString().padLeft(2, '0')} $month ${row[1]} 12:34:56.123457';
      equal(date.toDateTime(), expected, 'conversion $prefix');
      equal(numeric.format(date), number, 'numeric format $prefix');
      equal(named.format(date), text, 'named format $prefix');
      equal(
          (numeric.parseStrict(number, selector, true) as ChineseDateTime)
              .toDateTime(),
          expected,
          'numeric parse $prefix');
      equal(
          (named.parseStrict(text, selector, true) as ChineseDateTime)
              .toDateTime(),
          expected,
          'named parse $prefix');
      equal(
          (named.parseLoose(text.toUpperCase(), selector, true)
                  as ChineseDateTime)
              .toDateTime(),
          expected,
          'loose parse $prefix');
      days++;
      parses += 3;
    }
  }
  equal(days, 72674, 'supported day count');
  print(jsonEncode({
    'verifiedDays': days,
    'independentMonthFixtures': rows.length,
    'parseChecks': parses,
    'status': 'passed'
  }));
}
